import sys

def main():
    try:
        line = sys.stdin.read().strip()
        if not line:
            return
        R, C = map(int, line.split())
    except ValueError:
        return

    res = []

    if R == 1 and C == 1:
        res.append("URDL")
        print("".join(res))
        return

    for r in range(1, R + 1):
        for c in range(1, C + 1):
            if r == 1 and c == 1:
                continue

            if r > 1:
                res.append('U')
            if c > 1:
                res.append('R')

            res.append('D')
            res.append('L')

            if r > 1:
                res.append('D')
            if c > 1:
                res.append('L')

    print("".join(res))

if __name__ == "__main__":
    main()
